def find_longest(numbers: list[int]) -> int:
    if not numbers:
        raise ValueError("Input list must not be empty")

    max_num = numbers[0]
    max_len = len(str(max_num))

    for num in numbers[1:]:
        current_len = len(str(num))
        if current_len > max_len:
            max_len = current_len
            max_num = num

    return max_num
